const aiOutput = $input.first().json.output || '';

let parsed = {};
try {
  let cleaned = aiOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = aiOutput.match(/\{[^}]+\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) {}
  }
}

return [{ json: { aiParsed: parsed, citySearch: parsed.citySearch || '' } }];

// Build a compact lookup string from ALL municipalities
// The HTTP node returns the array as items, we need to collect them
const items = $input.all();
const citySearch = $('Parse AI Output').first().json.citySearch;
const aiParsed = $('Parse AI Output').first().json.aiParsed;

// The municipalities come as either a single item with array body,
// or multiple items. Handle both cases.
let municipalities = [];

if (items.length === 1) {
  const data = items[0].json;
  if (Array.isArray(data)) {
    municipalities = data;
  } else if (data && typeof data === 'object') {
    // Maybe the array is in a property
    const keys = Object.keys(data);
    // Check if it looks like an indexed object (0, 1, 2...)
    if (keys.length > 0 && keys[0] === '0') {
      municipalities = Object.values(data);
    } else {
      // Try common wrapper properties
      municipalities = data.body || data.data || data.result || [];
    }
  }
} else {
  // Multiple items = each item is a municipality
  municipalities = items.map(item => item.json);
}

// Build compact list: "id=descr" per line
const compactList = municipalities
  .filter(m => m && m.id && m.descr)
  .map(m => m.id + '=' + m.descr)
  .join('\n');

return [{ json: { 
  municipalityList: compactList,
  municipalityCount: municipalities.length,
  citySearch,
  aiParsed
}}];

