const municipalityOutput = ($input.first().json.output || '').trim();
const aiParsed = $('Prepare Municipality List').first().json.aiParsed;
const resultsSize = $('Search Form1').first().json['Πόσα αποτελέσματα;'] || '10';

const baseUrl = 'https://opendata-api.businessportal.gr/api/opendata/v1/companies';
const parts = [
  'resultsOffset=0',
  'resultsSize=' + encodeURIComponent(resultsSize),
  'resultsSortBy=' + encodeURIComponent('+arGemi'),
  'isActive=true'
];

// Extract just the numeric ID from AI output
const idMatch = municipalityOutput.match(/\d+/);
if (idMatch) {
  parts.push('municipalities=' + encodeURIComponent(idMatch[0]));
}

if (aiParsed.activities) {
  parts.push('activities=' + encodeURIComponent(aiParsed.activities));
}
if (aiParsed.name) {
  parts.push('name=' + encodeURIComponent(aiParsed.name));
}

const fullUrl = baseUrl + '?' + parts.join('&');

return [{ json: { fullUrl, municipalityId: idMatch ? idMatch[0] : 'NONE', aiParsed, resultsSize } }];

const response = $input.first().json;
const results = response.searchResults || [];

if (results.length === 0) {
  return [{ json: {
    'Company Name': 'Δεν βρέθηκαν αποτελέσματα',
    'Email': '',
    'Phone': '',
    'Website': '',
    'City': '',
    'Persons / Representatives': ''
  }}];
}

const rows = results.map(company => {
  const persons = (company.persons || []).map(p =>
    `${p.personName?.trim() || ''} (${p.role || ''})${p.percentage && p.percentage !== '-' ? ' - ' + p.percentage : ''}`
  ).join('; ');

  return {
    json: {
      'Company Name': company.coNameEl || '',
      'Email': company.email || '',
      'Phone': company.phone || '',
      'Website': company.url || '',
      'City': company.city || '',
      'Persons / Representatives': persons
    }
  };
});

return rows;
